#!/usr/bin/env bash
# gen-intents.sh - build the intent table from the `## Shortcuts` section of each skill.
#   <skill>/SKILL.md (hub skills) + config/intents.plugins.md (plugin skills, which can't be edited)
#     -> config/intents.json   read by config/hooks/intent-router.sh   (derived, do not edit)
#     -> config/AGENTS.md      short table between <!-- intents:start --> / <!-- intents:end -->
#
# Section format (inside a SKILL.md; in intents.plugins.md each skill gets its own `## <skill>` heading
# holding the same bullets instead of a `## Shortcuts` heading):
#   ## Shortcuts
#   - tools: `regex on the MCP tool name`
#   - bash: `regex on the Bash command`
#   - intent: <label> — `regex on the lowercased prompt` → `command or action`
# <base> inside a command is replaced by the hook with the repo's base branch.
#
# Usage: gen-intents.sh [--check]   (--check: exit 1 if a file is out of date, write nothing)
set -euo pipefail

HUB="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
OUT="$HUB/config/intents.json"
AGENTS="$HUB/config/AGENTS.md"
PLUGINS_MD="$HUB/config/intents.plugins.md"
CHECK=0
[ "${1:-}" = "--check" ] && CHECK=1
command -v jq >/dev/null || { echo "gen-intents: jq is required" >&2; exit 1; }

# parse <file> <skill> <mode>: mode "section" = only inside `## Shortcuts` (skill given),
# "plugins" = every `## <skill>` heading starts that skill's block.
# Emits TSV: skill kind a b c   (tools|bash: a=regex | intent: a=label b=regex c=command)
parse() {
  awk -v skill="$2" -v mode="$3" '
    function bt(s, n,   parts, k) { k = split(s, parts, "`"); return (2 * n <= k - 1) ? parts[2 * n] : "" }
    /^## / {
      if (mode == "plugins") { skill = $2; in_sec = 1 } else in_sec = ($0 ~ /^## Shortcuts[[:space:]]*$/)
      next
    }
    !in_sec { next }
    /^- tools:/ { printf "%s\ttools\t%s\t\t\n", skill, bt($0, 1); next }
    /^- bash:/ { printf "%s\tbash\t%s\t\t\n", skill, bt($0, 1); next }
    /^- intent:/ {
      label = $0; sub(/^- intent:[[:space:]]*/, "", label); sub(/[[:space:]]+—[[:space:]]+`.*$/, "", label)
      printf "%s\tintent\t%s\t%s\t%s\n", skill, label, bt($0, 1), bt($0, 2)
    }' "$1"
}

rows="$(mktemp)"; trap 'rm -f "$rows" "$rows.json" "$rows.agents" "$rows.agents.new"' EXIT

while IFS= read -r f; do
  parse "$f" "$(basename "$(dirname "$f")")" section
done < <(find "$HUB" -mindepth 3 -maxdepth 3 -name SKILL.md -not -path "$HUB/organizations/*" | sort) >"$rows"

[ -f "$PLUGINS_MD" ] && parse "$PLUGINS_MD" "" plugins >>"$rows"

# Validate every regex now so a typo fails here and not silently inside the hook.
bad=0
while IFS=$'\t' read -r skill kind a b c; do
  case "$kind" in
    tools|bash) re="$a" ;;
    intent) re="$b"; [ -n "$a" ] && [ -n "$c" ] || { echo "gen-intents: $skill: intent needs label, regex and command" >&2; bad=1; } ;;
    *) continue ;;
  esac
  [ -n "$re" ] || { echo "gen-intents: $skill: empty regex" >&2; bad=1; continue; }
  jq -n --arg re "$re" '"" | test($re)' >/dev/null 2>&1 || { echo "gen-intents: $skill: invalid regex: $re" >&2; bad=1; }
done <"$rows"
[ "$bad" -eq 0 ] || exit 1

jq -R -s '
  split("\n") | map(select(length > 0) | split("\t"))
  | group_by(.[0])
  | map({
      skill: .[0][0],
      tools: [ .[] | select(.[1] == "tools") | .[2] ],
      bash: [ .[] | select(.[1] == "bash") | .[2] ],
      intents: [ .[] | select(.[1] == "intent") | {label: .[2], re: .[3], cmd: .[4]} ]
    })
  | {"_comment": "Generated by scripts/gen-intents.sh from the Shortcuts sections of each skill. Do not edit.", skills: .}
' "$rows" >"$rows.json"

# Table for AGENTS.md: one line per skill, labels only (commands live in the skill's own section).
{
  echo "<!-- intents:start -->"
  echo "## Shortcuts"
  echo
  echo "Natural phrases map to a skill. Load the skill and use the command in its \`## Shortcuts\` section;"
  echo "Claude Code's \`intent-router\` hook injects this automatically. Outbound actions still need the user's OK."
  echo
  jq -r '.skills[] | select(.intents | length > 0) | "- `\(.skill)`: \([.intents[].label] | join(", "))"' "$rows.json"
  echo "<!-- intents:end -->"
} >"$rows.agents"

update_agents() { # prints the new AGENTS.md on stdout
  if grep -q '<!-- intents:start -->' "$AGENTS"; then
    awk -v block="$(cat "$rows.agents")" '
      /<!-- intents:start -->/ { print block; skip = 1; next }
      /<!-- intents:end -->/ { skip = 0; next }
      !skip { print }' "$AGENTS"
  else
    cat "$AGENTS"; echo; cat "$rows.agents"
  fi
}

if [ "$CHECK" -eq 1 ]; then
  rc=0
  cmp -s "$rows.json" "$OUT" || { echo "gen-intents: config/intents.json out of date" >&2; rc=1; }
  update_agents | cmp -s - "$AGENTS" || { echo "gen-intents: config/AGENTS.md intents table out of date" >&2; rc=1; }
  [ "$rc" -eq 0 ] && echo "gen-intents: up to date"
  exit "$rc"
fi

cp "$rows.json" "$OUT"
update_agents >"$rows.agents.new" && mv "$rows.agents.new" "$AGENTS"
echo "gen-intents: wrote config/intents.json ($(jq '[.skills[].intents[]] | length' "$OUT") intents, $(jq '.skills | length' "$OUT") skills) and the AGENTS.md table"
